from collections import deque

def flood_fill_6_neighbors(grid, start_positions, target_val):
    height, width = len(grid), len(grid[0])
    visited = [[False]*width for _ in range(height)]
    result = []

    for sr in range(height):
        for sc in range(width):
            if (sr, sc) in start_positions or grid[sr][sc] == target_val or grid[sr][sc] == 8:
                # Check if this 8 is adjacent to a 6 through a path of 8s
                queue = deque([(sr, sc)])
                visited[sr][sc] = True

                while queue:
                    curr_r, curr_c = queue.popleft()
                    result.append((curr_r, curr_c))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r+dr, curr_c+dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if not visited[nr][nc]:
                                if grid[nr][nc] in [6, 8]:
                                    visited[nr][nc] = True
                                    queue.append((nr, nc))

    return result

